# Store user message in conversation history
user_message = {
    "role": "user",
    "content": request.message
}
await state.add_message(conversation_id, user_message)

# *** INSERT ACTIVITY TRACKING HERE ***
# Update user activity timestamp (non-blocking)
try:
    from api.proactive.activity import update_activity
    await update_activity(request.user_id, state.redis_client)
except Exception as e:
    # Fire-and-forget: log error but don't fail chat flow
    logger.warning(
        f"Failed to update user activity: {str(e)}",
        extra={"user_id": request.user_id}
    )

