error-handling.example:
try:
    await update_activity(user_id, redis_client)
    logger.info(
        "User activity updated",
        extra={"user_id": user_id}
    )
except redis_exceptions.ConnectionError as e:
    logger.warning(
        f"Failed to update activity (Redis unavailable): {str(e)}",
        extra={"user_id": user_id}
    )
except Exception as e:
    logger.error(
        f"Unexpected error updating activity: {str(e)}",
        extra={"user_id": user_id},
        exc_info=True
    )

logging-standards.example:
logger.info(
    "User activity updated",
    extra={
        "user_id": user_id,
        "timestamp": timestamp,
        "key": key
    }
)

logger.warning(
    f"Failed to update user activity: {str(e)}",
    extra={
        "user_id": user_id,
        "error_type": type(e).__name__
    }
)

