@pytest.mark.asyncio async def test_update_activity_redis_error(redis_mock): """Test graceful degradation on Redis connection error.""" user_id = "test_user_123"
import redis.asyncio as redis_lib redis_mock.setex.side_effect = redis_lib.RedisError("Connection failed")
# Should not raise exception await update_activity(user_id, redis_mock)
# Verify it attempted the operation redis_mock.setex.assert_called_once()
